SELECT  coalesce(json_agg("root" ORDER BY "root.pg.published_at" DESC NULLS FIRST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."title" AS "title", "_root.or.author"."author" AS "author", "_root.ar.root.comments"."comments" AS "comments"       ) AS "_e"      ) ) AS "root", "_root.base"."published_at" AS "root.pg.published_at" FROM  (SELECT  *  FROM "public"."article"  WHERE (("public"."article"."author_id") = (('3')::integer))   ORDER BY "published_at" DESC NULLS FIRST LIMIT 20 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.author.base"."name" AS "name"       ) AS "_e"      ) ) AS "author" FROM  (SELECT  *  FROM "public"."author"  WHERE (("_root.base"."author_id") = ("id"))    LIMIT 1 ) AS "_root.or.author.base"      ) AS "_root.or.author" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("comments" ORDER BY "root.ar.root.comments.pg.id" ASC NULLS LAST), '[]' ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.comments.base"."body" AS "body"       ) AS "_e"      ) ) AS "comments", "_root.ar.root.comments.base"."id" AS "root.ar.root.comments.pg.id" FROM  (SELECT  *  FROM "public"."comment"  WHERE ((("_root.base"."id") = ("article_id")) AND (EXISTS  (SELECT  1  FROM "public"."article" AS "__be_0_article" WHERE (((("__be_0_article"."id") = ("public"."comment"."article_id")) AND ('true')) AND (('true') AND (((("__be_0_article"."author_id") = (('3')::integer)) AND ('true')) AND ('true'))))     )))   ORDER BY "id" ASC NULLS LAST LIMIT 5 ) AS "_root.ar.root.comments.base"    ORDER BY "root.ar.root.comments.pg.id" ASC NULLS LAST  ) AS "_root.ar.root.comments"      ) AS "_root.ar.root.comments" ON ('true')    ORDER BY "root.pg.published_at" DESC NULLS FIRST  ) AS "_root"
